// === НАСТРОЙКИ ===
const VALID_KEY = "secret123"; // Ваш секретный ключ
const LIMIT = 3; // Максимум запросов
const WINDOW_MS = 60 * 1000; // За 1 минуту (60 000 мс)

// 1. ПРОВЕРКА API-КЛЮЧА
// Node-RED приводит все заголовки к нижнему регистру, поэтому ищем 'x-api-key'
const providedKey = msg.req.headers['x-api-key'];

if (providedKey !== VALID_KEY) {
    // Если ключ неверный или отсутствует — возвращаем 401
    msg.statusCode = 401;
    msg.payload = { error: "Unauthorized: Invalid or missing X-API-Key" };
    return msg;
}

// 2. ПРОВЕРКА RATE LIMIT
// Используем global context, чтобы счетчик жил между разными запросами
let clientData = global.get("rateLimitData") || {};

// Если для этого ключа еще нет записи, создаем её
if (!clientData[providedKey]) {
    clientData[providedKey] = { count: 0, windowStart: Date.now() };
}

const now = Date.now();

// Если прошло больше времени, чем окно (1 минута) — сбрасываем счетчик
if (now - clientData[providedKey].windowStart > WINDOW_MS) {
    clientData[providedKey].count = 0;
    clientData[providedKey].windowStart = now;
}

// Увеличиваем счетчик
clientData[providedKey].count++;

// Сохраняем обновленные данные обратно в global context
global.set("rateLimitData", clientData);

// Проверяем, не превышен ли лимит
if (clientData[providedKey].count > LIMIT) {
    msg.statusCode = 429; // Too Many Requests
    msg.payload = { error: "Too Many Requests: Rate limit exceeded" };
    return msg;
}

// === ЕСЛИ ВСЕ ПРОВЕРКИ ПРОЙДЕНЫ ===
// Возвращаем успешный ответ (или передаем управление дальше)
msg.statusCode = 200;
msg.payload = {
    message: "Access granted!",
    requestNumber: clientData[providedKey].count,
    limit: LIMIT
};

return msg;
